<script setup lang="ts">
import { computed,ref } from 'vue'
import { api,errorText } from '../api'
import { date } from '../domain'
import type { Row } from '../domain'
import { useAuth } from '../stores/auth'
import FieldDesigner from './FieldDesigner.vue'
const props=defineProps<{ task:Row }>(),emit=defineEmits<{ changed:[] }>(),auth=useAuth()
const mode=ref(''),busy=ref(false),error=ref(''),version=ref(0),fields=ref<Row[]>([]),values=ref<Row>({}),enabled=ref(false),status=ref('NONE'),feedback=ref('')
const data=computed<Row>(()=>props.task.keyWorkData||{fields:[],values:{},enabled:false,coordinationStatus:'NONE',feedback:''})
const mayUpdate=computed(()=>!auth.me?.permissions||auth.me.permissions.includes('TASK_UPDATE'))
const active=computed(()=>!['COMPLETED','CANCELLED'].includes(props.task.status))
const labels:Row={NONE:'无需协调',PENDING:'待协调',IN_PROGRESS:'协调中',RESOLVED:'已解决'}
function snapshot(value:Row){if(!value)return '无';const lines=(value.fields||[]).map((field:Row)=>`${field.name}：${value.values?.[field.id]??'—'}`);if(value.enabled){lines.push(`协调状态：${labels[value.coordinationStatus]||'无需协调'}`);lines.push(`领导反馈：${value.feedback||'—'}`)}return lines.join('\n')||'无字段'}
function edit(which:string){mode.value=which;version.value=props.task.version;fields.value=JSON.parse(JSON.stringify(data.value.fields||[]));values.value=JSON.parse(JSON.stringify(data.value.values||{}));enabled.value=!!data.value.enabled;status.value=data.value.coordinationStatus||'NONE';feedback.value=data.value.feedback||'';error.value=''}
function openFill(){if(mode.value==='fill')return;if(mode.value){error.value='当前正在编辑，请先保存或取消。';return}edit('fill')}
defineExpose({openFill})
async function save(){if(busy.value)return;busy.value=true;error.value='';try{let payload:Row={version:version.value};if(mode.value==='configure')payload={...payload,fields:fields.value,keyWork:enabled.value};else if(mode.value==='fill')payload={...payload,values:values.value};else payload={...payload,coordinationStatus:status.value,feedback:feedback.value};await api.post(`/tasks/${props.task.id}/key-work/${mode.value}`,payload);mode.value='';emit('changed')}catch(e){error.value=errorText(e)}finally{busy.value=false}}
</script>
<template><section class="key-work"><div class="row-between"><div><h2>{{ data.enabled?`重点工作填报`:`任务填报` }}</h2><p class="muted">记录工作进展、问题和建议；部门完成进度可在页面上方更新。</p></div><el-button v-if="task.canConfigureFields&&mayUpdate&&active&&!mode" @click="edit('configure')">配置字段</el-button></div>
<el-alert v-if="error" :title="error" type="error" show-icon :closable="false"/>
<template v-if="mode==='configure'"><el-checkbox v-model="enabled">纳入重点工作汇总</el-checkbox><FieldDesigner v-model:fields="fields" :values="values"/></template>
<template v-else-if="mode==='fill'"><el-form label-position="top"><el-form-item v-for="field in fields" :key="field.id" :label="field.name" :required="field.required"><el-input v-if="field.type==='TEXT'" v-model="values[field.id]" type="textarea" maxlength="4000"/><el-input-number v-else-if="field.type==='NUMBER'" v-model="values[field.id]"/><el-date-picker v-else-if="field.type==='DATE'" v-model="values[field.id]" type="date" value-format="YYYY-MM-DD"/><el-select v-else v-model="values[field.id]" clearable><el-option v-for="option in field.options" :key="option" :label="option" :value="option"/></el-select></el-form-item></el-form></template>
<template v-else-if="mode==='feedback'"><el-form label-position="top"><el-form-item label="协调状态"><el-select v-model="status"><el-option v-for="(label,key) in labels" :key="key" :label="label" :value="key"/></el-select></el-form-item><el-form-item label="领导反馈"><el-input v-model="feedback" type="textarea" maxlength="4000"/></el-form-item></el-form></template>
<template v-else><el-empty v-if="!data.fields?.length" description="尚未配置任务填报字段" :image-size="60"/><div v-else class="field-values"><article v-for="field in data.fields" :key="field.id" class="field-value"><h3>{{ field.name }}<span v-if="field.required" class="required"> 必填</span></h3><p v-if="data.values?.[field.id]!==undefined&&data.values?.[field.id]!==null&&data.values?.[field.id]!==''" class="pre-wrap">{{ data.values[field.id] }}</p><p v-else class="empty-field">尚未填写</p></article></div><el-button v-if="task.canFillFields&&mayUpdate&&active&&data.fields?.length" type="primary" plain @click="edit('fill')">填写或更新</el-button><div v-if="data.enabled" class="coordination"><h3>领导协调</h3><p>协调状态：{{ labels[data.coordinationStatus]||'无需协调' }}</p><p class="pre-wrap">领导反馈：{{ data.feedback||'—' }}</p><el-button v-if="task.canConfigureFields&&mayUpdate&&active" @click="edit('feedback')">更新协调反馈</el-button></div><el-collapse v-if="task.keyWorkHistory?.length"><el-collapse-item title="填报和配置历史"><article v-for="record in task.keyWorkHistory" :key="record.id" class="history"><b>{{ ({CONFIGURE:'字段配置',FILL:'更新填报',FEEDBACK:'协调反馈'} as Row)[record.status]||record.status }}</b> · {{ record.actorName||'用户 '+record.actorId }} · {{ date(record.createdAt) }}<details><summary>查看变更前后</summary><p>变更前</p><pre>{{ snapshot(record.before) }}</pre><p>变更后</p><pre>{{ snapshot(record.after) }}</pre></details></article></el-collapse-item></el-collapse></template>
<div v-if="mode" class="actions"><el-button @click="mode=''">取消</el-button><el-button type="primary" :loading="busy" @click="save">保存</el-button></div></section></template>
<style scoped>.key-work{border-top:1px solid var(--el-border-color);margin-top:24px;padding-top:20px}.field-values{display:grid;grid-template-columns:repeat(auto-fit,minmax(min(220px,100%),1fr));gap:12px;margin:16px 0}.field-value{min-width:0;border:1px solid #e1e8f0;border-radius:7px;padding:14px;background:#fbfcfe}.field-value h3{font-size:13px;margin:0 0 8px;color:#40566d}.field-value p{margin:0;overflow-wrap:anywhere;line-height:1.7}.empty-field{color:#8997a7;font-size:12px}.required{font-size:11px;font-weight:400;color:#b16c19}.coordination,.history{border-top:1px solid var(--el-border-color);padding:14px 0}.actions{margin-top:16px}pre{white-space:pre-wrap;overflow-wrap:anywhere}</style>
